{"code": "import json, sys, numpy as np, math, scipy.optimize as opt
input_data_str = sys.stdin.read()
data_list = json.loads(input_data_str)
outputs = np.array([row[0] for row in data_list])
P = np.array([row[2] for row in data_list])

def logistic(P, r, K):
    return r * P * (1 - P / K)

def loss(params):
    r, K = params
    pred = logistic(P, r, K)
    return np.mean((pred - outputs)**2)

res = opt.minimize(loss, [0.001, 200], method='BFGS')
print(res.x, res.fun)
pred = logistic(P, *res.x)
mape = np.mean(np.abs(pred-outputs)/np.abs(outputs))
print('MAPE', mape)"}

