outputs=np.array([row[0] for row in data])
inputs=np.array([row[1:] for row in data])
t=inputs[:,0]; P=inputs[:,1]

feature_sets=[
    ['1','t','P','tP','t2','P2'],
    ['1','t','P','tP','t2','P2','t3'],
    ['1','t','P','tP','t2','P2','t3','t2P'],
    ['1','t','P','tP','t2','P2','t3','tP2'],
    ['1','t','P','tP','t2','P2','t3','t2P','tP2'],
    ['1','t','P','tP','t2','P2','t3','t2P','tP2','P3'],
    ['1','t','P','tP','t2','P2','t3','t2P','tP2','P3','t4'],
]

for fs in feature_sets:
    # create X
    X=list()
    for f in fs:
        if f=='1':
            X.append(np.ones_like(t))
        elif f=='t':
            X.append(t)
        elif f=='P':
            X.append(P)
        elif f=='tP':
            X.append(t*P)
        elif f=='t2':
            X.append(t**2)
        elif f=='P2':
            X.append(P**2)
        elif f=='t3':
            X.append(t**3)
        elif f=='t4':
            X.append(t**4)
        elif f=='t2P':
            X.append(t**2*P)
        elif f=='tP2':
            X.append(t*P**2)
        elif f=='P3':
            X.append(P**3)
    X=np.vstack(X).T
    coeffs=np.linalg.lstsq(X,outputs,rcond=None)[0]
    pred=X.dot(coeffs)
    mask=outputs!=0
    mape=np.mean(np.abs((pred[mask]-outputs[mask])/outputs[mask]))
    print(fs, 'MAPE',mape)
"}

